// WKSTA_USER_ENUM_STRUCT ([MS-WKST]). Generated by tools/idlgen; verify pointer/array tags.
type WKSTA_USER_ENUM_STRUCT struct {
	Level         ndr.DWORD
	WkstaUserInfo WKSTA_USER_ENUM_UNION
}

// WKSTA_USER_ENUM_UNION is a discriminated union ([MS-WKST] 2.2.5.14). switch_type is DWORD;
// the discriminant is transmitted inline before the selected arm ([C706] 14.3.8). Every arm
// is a [unique] pointer container (LPWKSTA_USER_INFO_0_CONTAINER, ...), so each arm is a
// pointer field with `unique`; an inline-value arm would drop the container referent id.
type WKSTA_USER_ENUM_UNION struct {
	Tag    ndr.DWORD                    `ndr:"switch"`
	Level0 *WKSTA_USER_INFO_0_CONTAINER `ndr:"case=0,unique"`
	Level1 *WKSTA_USER_INFO_1_CONTAINER `ndr:"case=1,unique"`
}
